$ErrorActionPreference='Stop'; $root=Join-Path $PSScriptRoot '..'; $tmp=Join-Path ([System.IO.Path]::GetTempPath()) ('cursorpage-'+[guid]::NewGuid().ToString('N')); New-Item -ItemType Directory $tmp | Out-Null; try { Copy-Item (Join-Path $root 'starter/AuditPaging.cs') (Join-Path $tmp 'AuditPaging.cs'); Copy-Item (Join-Path $root 'verification/Verify.cs') (Join-Path $tmp 'Program.cs'); Copy-Item (Join-Path $root 'verification/Verify.csproj') (Join-Path $tmp 'Verify.csproj'); dotnet run --project (Join-Path $tmp 'Verify.csproj'); if ($LASTEXITCODE -ne 0) { throw 'Verification failed' } } finally { Remove-Item $tmp -Recurse -Force -ErrorAction SilentlyContinue }
